('samsung-galaxy-buds3-pro-silver', 'Samsung Galaxy Buds3 Pro Wireless ANC Earbuds - Silver', 'audio', 195000, 189000, 158000, 35, 0.05, '/assets/products/samsung-buds3-pro-silver.webp', 'Samsung''s most advanced earbuds with adaptive noise cancellation that automatically adjusts to your environment. The dual-driver system with planar tweeter delivers studio-quality audio, while the redesigned stem with blade lights provides intuitive touch controls.', 1, unixepoch('2026-06-16'), 1, 158000, '/assets/products/samsung-buds3-pro-silver.webp', 178000, 4.7, 1, 'Samsung', 1, 1),

('samsung-galaxy-buds-fe-graphite', 'Samsung Galaxy Buds FE Wireless Earbuds with ANC - Graphite Black', 'audio', 75000, 72900, 62000, 55, 0.05, '/assets/products/samsung-buds-fe-graphite.webp', 'Experience Samsung''s signature active noise cancellation at an accessible price. The three-microphone system with AI voice pickup ensures crystal-clear calls, while the wingtip design keeps the buds secure during workouts. 30-hour total battery with the charging case.', 1, unixepoch('2026-06-16'), 1, 62000, '/assets/products/samsung-buds-fe-graphite.webp', 69000, 4.6, 1, 'Samsung', 1, 1),

('samsung-galaxy-buds2-pro-bora-purple', 'Samsung Galaxy Buds2 Pro Wireless Earbuds - Bora Purple', 'audio', 145000, 139000, 118000, 30, 0.05, '/assets/products/samsung-buds2-pro-purple.webp', 'The predecessor that still delivers premium 24-bit Hi-Fi audio with coaxial dual speakers. Intelligent ANC with voice detect automatically switches to ambient mode when you speak. The IPX7 water resistance handles rain and sweat without worry.', 1, unixepoch('2026-06-16'), 1, 118000, '/assets/products/samsung-buds2-pro-purple.webp', 132000, 4.6, 0, 'Samsung', 1, 1),

('samsung-galaxy-watch7-44mm-lte', 'Samsung Galaxy Watch7 44mm LTE Smartwatch - Green Fabric Band', 'wearables', 380000, 369000, 315000, 15, 0.06, '/assets/products/samsung-watch7-44-lte.webp', 'Stay connected without your phone with LTE cellular capability. The BioActive Sensor 2.0 provides comprehensive health tracking including heart rate, ECG, blood pressure, and body composition analysis. Wear OS 5 with One UI Watch 6 offers seamless Galaxy integration.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/samsung-watch7-44-lte.webp', 348000, 4.7, 1, 'Samsung', 1, 1),

('samsung-galaxy-watch-fe-40mm', 'Samsung Galaxy Watch FE 40mm Smartwatch - Black Sport Band', 'wearables', 165000, 159000, 132000, 20, 0.05, '/assets/products/samsung-watch-fe-40.webp', 'Essential Samsung smartwatch features at an accessible price. The 1.2-inch Super AMOLED display with sapphire crystal glass, BioActive sensor for heart rate and body composition, sleep coaching, and 100+ workout tracking modes make this the perfect entry into wearable tech.', 1, unixepoch('2026-06-16'), 1, 132000, '/assets/products/samsung-watch-fe-40.webp', 149000, 4.5, 0, 'Samsung', 1, 1),

('samsung-galaxy-fit3-fitness-tracker', 'Samsung Galaxy Fit3 Fitness Tracker with AMOLED Display - Grey', 'wearables', 65000, 63900, 52000, 30, 0.02, '/assets/products/samsung-fit3-grey.webp', 'Track your fitness in style with a vivid 1.6-inch AMOLED display that''s 45% wider than the previous generation. The aluminum body with IP68 water resistance, 13-day battery life, and automatic workout detection make this the ultimate companion for active lifestyles.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/samsung-fit3-grey.webp', 59000, 4.5, 1, 'Samsung', 1, 1),

('samsung-galaxy-smarttag2-4pack', 'Samsung Galaxy SmartTag2 4-Pack Item Tracker Bundle - Black', 'accessories', 65000, 63900, 52000, 25, 0.08, '/assets/products/samsung-smarttag2-4pack.webp', 'Track your valuables with Samsung''s upgraded tracker featuring an IP67 water and dust resistant design, a battery that lasts up to 700 days, and Compass View that guides you with an arrow when you''re within range. The Galaxy Find network helps locate items miles away.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/samsung-smarttag2-4pack.webp', 59000, 4.6, 1, 'Samsung', 1, 1),

('samsung-15w-wireless-charger-pad', 'Samsung 15W Fast Wireless Charger Pad with LED Indicator - White', 'chargers', 22000, 21500, 17500, 55, 0.15, '/assets/products/samsung-wireless-pad-15w.webp', 'Drop and charge with Samsung''s fast wireless charging pad. The soft LED indicator confirms charging without disturbing sleep, while the built-in cooling fan prevents overheating during extended charging sessions. Compatible with all Qi-certified smartphones and earbuds.', 1, unixepoch('2026-06-16'), 1, 17500, '/assets/products/samsung-wireless-pad-15w.webp', 20500, 4.5, 1, 'Samsung', 1, 1),

('samsung-wireless-charger-trio-pad', 'Samsung Wireless Charger Trio - Charge 3 Devices Simultaneously - Black', 'chargers', 55000, 53900, 45000, 25, 0.35, '/assets/products/samsung-trio-pad.webp', 'Charge your Galaxy phone, Watch, and Buds simultaneously on one sleek pad. Six internal coils provide generous placement flexibility, while the LED indicators confirm each device is charging. The included 25W wall adapter powers everything at full speed.', 1, unixepoch('2026-06-16'), 1, 45000, '/assets/products/samsung-trio-pad.webp', 50500, 4.6, 0, 'Samsung', 1, 1),

('samsung-usbc-to-usbc-5a-cable-2m', 'Samsung 5A USB-C to USB-C Fast Charging Cable 2m Braided - Black', 'accessories', 8500, 8200, 6500, 150, 0.06, '/assets/products/samsung-usbc-5a-2m.webp', 'Official Samsung cable engineered for 45W Super Fast Charging 2.0 on Galaxy devices. The 5A rating, double-braided jacket, and reinforced aluminum connectors ensure reliable high-speed charging and data transfer through thousands of plug cycles and daily use.', 1, unixepoch('2026-06-16'), 1, 6500, '/assets/products/samsung-usbc-5a-2m.webp', 7600, 4.6, 1, 'Samsung', 1, 0),

