('itel-25w-pd-wall-charger', 'itel 25W PD USB-C Wall Charger with Fast Charge Protocol - White', 'chargers', 5500, 5200, 4200, 160, 0.07, '/assets/products/itel-25w-charger.webp', 'Charge your itel phone at maximum speed with this official 25W Power Delivery charger. The compact design with foldable plug fits easily in pockets and bags, while the intelligent chip protects against overcurrent, overheating, and short circuits.', 1, unixepoch('2026-06-16'), 1, 4200, '/assets/products/itel-25w-charger.webp', 4900, 4.4, 1, 'itel', 1, 1),

