('itel-smartwatch-active-2', 'itel Smart Watch Active 2 with SpO2 & Heart Rate - Matte Black', 'wearables', 14500, 13900, 11200, 60, 0.05, '/assets/products/itel-watch-active-2.webp', 'Track your health 24/7 with continuous heart rate, blood oxygen, and sleep monitoring. The 1.8-inch HD color touchscreen, IP68 water resistance, 60+ sports modes, and 10-day battery make this the perfect affordable fitness companion for active Nigerians.', 1, unixepoch('2026-06-16'), 1, 11200, '/assets/products/itel-watch-active-2.webp', 13200, 4.3, 1, 'itel', 1, 1),

