('usb-c-to-hdmi-adapter-4k60', 'USB-C to HDMI Adapter 4K 60Hz with HDR Support - Aluminum Grey', 'accessories', 9500, 9200, 7200, 90, 0.04, '/assets/products/usbc-hdmi-4k60-adapter.webp', 'Mirror or extend your laptop screen to any HDMI monitor or TV at crystal-clear 4K 60Hz resolution. The braided cable with reinforced aluminum connectors supports HDR10 for vibrant colors, while Thunderbolt 3/4 and USB4 compatibility ensures broad device support.', 1, unixepoch('2026-06-16'), 1, 7200, '/assets/products/usbc-hdmi-4k60-adapter.webp', 8500, 4.5, 1, 'Generic', 1, 1),

